ref rP
ref rObj
float fRes
float fDx
Begin Function { }
let rP := GetFormFromMod "FalloutNV.esm" "14"
let fDx := (rP.GetPos X) - (rP.AuxVarGetFlt "*nvfCX")
let fRes := (rP.GetPos Y) - (rP.AuxVarGetFlt "*nvfCY")
let fRes := (fDx * fDx) + (fRes * fRes)
SetFunctionValue (fRes > 100)
End

